files.content:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

[hidden] {
  display: none !important;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  background: #1a1a2e;
  color: #e0e0e0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.card {
  background: #16213e;
  border: 4px solid #0f3460;
  border-radius: 8px;
  padding: 24px;
  max-width: 400px;
  width: 100%;
  text-align: center;
  box-shadow: 0 8px 0 #0f3460;
}

h1 {
  font-size: 1.5rem;
  margin-bottom: 24px;
  color: #e94560;
  text-transform: uppercase;
  letter-spacing: 2px;
}

.settings {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  margin-bottom: 24px;
  text-align: left;
}

label {
  font-size: 0.9rem;
  color: #a0a0b0;
}

input {
  font-size: 1rem;
  padding: 8px;
  border: 2px solid #0f3460;
  border-radius: 4px;
  background: #1a1a2e;
  color: #e0e0e0;
  width: 100%;
}

input:focus {
  outline: 2px solid #e94560;
  outline-offset: 2px;
}

.display {
  margin-bottom: 24px;
}

#phase {
  font-size: 1.2rem;
  font-weight: bold;
  color: #e94560;
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-bottom: 4px;
}

#round {
  font-size: 1rem;
  color: #a0a0b0;
  margin-bottom: 8px;
}

#timer {
  font-size: 3rem;
  font-weight: bold;
  font-variant-numeric: tabular-nums;
  color: #e0e0e0;
  letter-spacing: 2px;
}

.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
}

button {
  font-size: 1rem;
  padding: 10px 20px;
  border: none;
  border-radius: 4px;
  background: #0f3460;
  color: #e0e0e0;
  cursor: pointer;
  font-weight: bold;
  text-transform: uppercase;
  letter-spacing: 1px;
  transition: background 0.2s, transform 0.1s;
}

button:hover:not(:disabled) {
  background: #e94560;
}

button:focus-visible {
  outline: 2px solid #e94560;
  outline-offset: 2px;
}

button:active:not(:disabled) {
  transform: translateY(2px);
}

button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

#message {
  margin-top: 24px;
  font-size: 1.2rem;
  font-weight: bold;
  color: #e94560;
  text-transform: uppercase;
  letter-spacing: 2px;
}

@media (max-width: 400px) {
  .card {
    padding: 16px;
  }
  h1 {
    font-size: 1.2rem;
  }
  #timer {
    font-size: 2.5rem;
  }
  button {
    padding: 8px 16px;
    font-size: 0.9rem;
  }
}

const workInput = document.getElementById('work');
const restInput = document.getElementById('rest');
const roundsInput = document.getElementById('rounds');
const phaseEl = document.getElementById('phase');
const roundEl = document.getElementById('round');
const timerEl = document.getElementById('timer');
const startBtn = document.getElementById('start');
const stopBtn = document.getElementById('stop');
const resetBtn = document.getElementById('reset');
const messageEl = document.getElementById('message');

let intervalId = null;
let currentPhase = 'idle';
let currentRound = 0;
let totalRounds = 0;
let timeLeft = 0;
let workSeconds = 30;
let restSeconds = 10;

function formatTime(seconds) {
  const m = Math.floor(seconds / 60);
  const s = seconds % 60;
  return `${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`;
}

function updateDisplay() {
  timerEl.textContent = formatTime(timeLeft);
  roundEl.textContent = `Round ${currentRound} / ${totalRounds}`;
  if (currentPhase === 'work') {
    phaseEl.textContent = 'Work';
  } else if (currentPhase === 'rest') {
    phaseEl.textContent = 'Rest';
  } else if (currentPhase === 'done') {
    phaseEl.textContent = 'Done';
  } else {
    phaseEl.textContent = 'Ready';
  }
}

function tick() {
  if (timeLeft > 0) {
    timeLeft--;
    updateDisplay();
    return;
  }
  if (currentPhase === 'work') {
    if (currentRound < totalRounds) {
      currentPhase = 'rest';
      timeLeft = restSeconds;
    } else {
      endWorkout();
    }
  } else if (currentPhase === 'rest') {
    if (currentRound < totalRounds) {
      currentRound++;
      currentPhase = 'work';
      timeLeft = workSeconds;
    } else {
      endWorkout();
    }
  }
  updateDisplay();
}

function endWorkout() {
  clearInterval(intervalId);
  intervalId = null;
  currentPhase = 'done';
  timeLeft = 0;
  updateDisplay();
  messageEl.hidden = false;
  startBtn.disabled = false;
  stopBtn.disabled = true;
  if ('speechSynthesis' in window) {
    const utterance = new SpeechSynthesisUtterance('Workout complete');
    speechSynthesis.speak(utterance);
  }
}

function start() {
  if (intervalId) return;
  workSeconds = Math.max(1, parseInt(workInput.value) || 30);
  restSeconds = Math.max(1, parseInt(restInput.value) || 10);
  totalRounds = Math.max(1, parseInt(roundsInput.value) || 3);
  currentRound = 1;
  currentPhase = 'work';
  timeLeft = workSeconds;
  messageEl.hidden = true;
  startBtn.disabled = true;
  stopBtn.disabled = false;
  updateDisplay();
  intervalId = setInterval(tick, 1000);
}

function stop() {
  clearInterval(intervalId);
  intervalId = null;
  startBtn.disabled = false;
  stopBtn.disabled = true;
}

function reset() {
  stop();
  currentPhase = 'idle';
  currentRound = 0;
  totalRounds = 0;
  timeLeft = 0;
  messageEl.hidden = true;
  updateDisplay();
}

startBtn.addEventListener('click', start);
stopBtn.addEventListener('click', stop);
resetBtn.addEventListener('click', reset);

reset();
